insert into private.finance_receivers(id,organization_id,unit_id,provider,environment,status,external_id,holder,holder_confirmed,beneficiary_units,account_id,created_by,expires_at) values('ff400000-0000-4000-8000-000000000001',current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'mercado_pago','production','configured','123','Titular fictício',true,array[current_setting('f4.unit')::uuid],'df400000-0000-4000-8000-000000000001','af400000-0000-4000-8000-000000000001',now()+interval '1 hour');
